import type { Metadata } from "next";

/** Per-page metadata with canonical URL and Open Graph. OG image is generated by app/opengraph-image (step 8). */
export function pageMeta(title: string, description: string, path: string): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      siteName: "Zekured",
      locale: "en_NG",
      type: "website",
    },
  };
}
